<script setup>
import { computed, onMounted, ref } from 'vue'

const props = defineProps({ page: String, permissions: Array, roles: Array, baseCurrency: String })
const allowed = new Set(props.permissions || [])
const can = (permission) => allowed.has(permission)
const view = computed(() => (props.page || '').replace('accounting-', '') || 'dashboard')
const titles = {
  dashboard: ['Accounting Dashboard', 'Monthly demand, approved budget authority, and funding coverage.'],
  overview: ['Accounting Overview', 'Review forecast demand and the current budget position.'],
  'shipment-demand': ['Shipment Demand Forecast', 'Forecast source volumes by month and confidence.'],
  'funding-requirements': ['Funding Requirements', 'Approved funding demand and separate provisional estimate assumptions.'],
  'budget-plans': ['Monthly Budget Plans', 'Prepare, submit, review, and approve monthly funding plans.'],
  'budget-allocations': ['Budget Allocations', 'Reserve approved budget authority for operational funding needs.'],
  'cash-forecast': ['Cash Requirement Forecast', 'Forecast requirements by source month; payment dates and cash balances are not recorded.'],
  'commitments-actuals': ['Commitments & Actuals', 'Operational commitments and expense actuals are not integrated.'],
  'budget-variance': ['Budget Variance Reports', 'Compare available requested, approved, and allocated values by currency.'],
  'budget-history': ['Budget History', 'Trace budget changes, reviews, approvals, and allocations.'],
}
const title = computed(() => titles[view.value] || titles.dashboard)
const busy = ref(true)
const error = ref('')
const success = ref('')
const dashboard = ref(null)
const requirements = ref([])
const plans = ref([])
const selected = ref(null)
const filters = ref({ month: new Date().toISOString().slice(0, 7), client: '', mode: '', category: '', status: '' })
const showCreate = ref(false)
const editing = ref(false)
const form = ref({ budget_month: new Date().toISOString().slice(0, 7), currency: props.baseCurrency || 'PHP', explanation: '', lines: [{ category: 'shipping_line', requested_amount: '0.00', description: '' }] })
const editForm = ref({ explanation: '', reason: '', lines: [] })
const reviewRemarks = ref('')
const allocationForm = ref({ budget_line_id: '', amount: '', requirement_source: '', purpose: '' })
const auditHistory = ref([])
const cashPeriod = ref('month')
const currencySummary = computed(() => Object.entries(dashboard.value?.approved_by_currency || {}).map(([currency, amount]) => `${currency} ${Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2 })}`).join(' · ') || 'Not recorded')
const categories = [
  ['shipping_line', 'Shipping line fees'], ['ocean_air_freight', 'Freight / carrier charges'], ['port_terminal', 'Port / terminal charges'],
  ['customs_processing', 'Customs processing'], ['trucking_transport', 'Transport / trucking'], ['forwarding', 'Forwarding'],
  ['warehousing', 'Warehousing'], ['handling_labor', 'Handling and labor'], ['insurance', 'Insurance'], ['documentation', 'Documentation'],
  ['cash_advance_cost', 'Operating cash advances'], ['miscellaneous', 'Other operating costs'], ['contingency', 'Contingency'], ['duties_taxes', 'Duties and taxes'], ['other', 'Other'],
]
const money = (amount, currency) => amount == null ? 'Not recorded' : `${currency || ''} ${Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
const api = async (url, options = {}) => {
  const response = await fetch(url, { credentials: 'same-origin', headers: { Accept: 'application/json', ...(options.body ? { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' } : {}), ...options.headers }, ...options })
  const body = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(Object.values(body.errors || {}).flat().join(' ') || body.message || (response.status === 403 ? 'You are not authorized to view this financial data.' : `Request failed (${response.status}).`))
  return body
}
const load = async () => {
  busy.value = true; error.value = ''; success.value = ''
  try {
    if (can('accounting.dashboard.view')) dashboard.value = await api('/api/accounting/dashboard')
    if (can('funding-requirements.view')) {
      const params = new URLSearchParams(Object.fromEntries(Object.entries(filters.value).filter(([, value]) => value)))
      const result = await api(`/api/accounting/funding-requirements?${params}`); requirements.value = result.data || []
    }
    if (can('budgets.view')) {
      const result = await api('/api/accounting/budgets'); plans.value = result.data || []
      if (selected.value?.data?.id) await openPlan(selected.value.data.id)
    }
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
const openPlan = async (id) => { try { selected.value = await api(`/api/accounting/budgets/${id}`); allocationForm.value.budget_line_id = selected.value.lines?.[0]?.id || ''; filters.value.month = selected.value.data.budget_month.slice(0, 7); if (can('funding-requirements.view')) { const params = new URLSearchParams({ month: filters.value.month }); requirements.value = (await api(`/api/accounting/funding-requirements?${params}`)).data || [] } if (view.value === 'budget-history') auditHistory.value = (await api(`/api/accounting/budgets/${id}/history`)).data || [] } catch (e) { error.value = e.message } }
const beginEdit = () => { editForm.value = { explanation: selected.value.data.explanation || '', reason: '', lines: selected.value.lines.map(line => ({ category: line.category, requested_amount: String(line.requested_amount), description: line.description || '', adjustment_reason: line.adjustment_reason || '' })) }; editing.value = true }
const addLine = () => form.value.lines.push({ category: 'other', requested_amount: '0.00', description: '' })
const removeLine = (index) => { if (form.value.lines.length > 1) form.value.lines.splice(index, 1) }
const createPlan = async () => {
  try { const result = await api('/api/accounting/budgets', { method: 'POST', body: JSON.stringify(form.value) }); showCreate.value = false; success.value = `${result.data.reference} saved as draft.`; await load(); await openPlan(result.data.id) }
  catch (e) { error.value = e.message }
}
const updatePlan = async () => { try { await api(`/api/accounting/budgets/${selected.value.data.id}`, { method: 'PUT', body: JSON.stringify(editForm.value) }); editing.value = false; success.value = 'Draft budget saved.'; await load() } catch (e) { error.value = e.message } }
const sendAction = async (url, body = {}) => { try { await api(url, { method: 'POST', body: JSON.stringify(body) }); success.value = 'Budget updated successfully.'; await load() } catch (e) { error.value = e.message } }
const saveAllocation = async () => { await sendAction(`/api/accounting/budgets/${selected.value.data.id}/allocate`, allocationForm.value) }
onMounted(load)
</script>

<template>
  <div class="budget-workspace">
    <header class="budget-heading"><div><div class="ifc-kicker">INTERFREIGHT GROUP / PHASE 4 · ACCOUNTING</div><h1>{{ title[0] }}</h1><p>{{ title[1] }}</p></div><button v-if="view === 'budget-plans' && can('budgets.create')" class="ifc-primary" @click="showCreate = true">+ New monthly plan</button><button v-else class="budget-refresh" :disabled="busy" @click="load">{{ busy ? 'Refreshing…' : 'Refresh data' }}</button></header>
    <div v-if="error" class="budget-alert" role="alert">{{ error }}</div><div v-if="success" class="budget-success" role="status">{{ success }}</div>

    <template v-if="view === 'dashboard' || view === 'overview'">
      <section class="budget-kpis">
        <article><small>Current month funding requirement</small><strong>{{ dashboard?.demand?.totals_by_currency?.length ? dashboard.demand.totals_by_currency.map(x => money(x.amount, x.currency)).join(' · ') : 'Not recorded' }}</strong><span>{{ filters.month }} · forecast scope</span></article>
        <article><small>Next month funding requirement</small><strong>{{ dashboard?.next_month_demand?.totals_by_currency?.length ? dashboard.next_month_demand.totals_by_currency.map(x => money(x.amount, x.currency)).join(' · ') : 'Not recorded' }}</strong><span>Approved estimate demand</span></article>
        <article><small>Total budget requested</small><strong>{{ dashboard?.requested_by_currency ? Object.entries(dashboard.requested_by_currency).map(([c, a]) => money(a, c)).join(' · ') || 'Not recorded' : 'Not recorded' }}</strong><span>Current month plans</span></article>
        <article><small>Total approved budget</small><strong>{{ currencySummary }}</strong><span>Current month · {{ dashboard?.pending_approvals ?? 'Not recorded' }} pending review</span></article>
        <article><small>Commitments</small><strong>Not integrated</strong><span>No operational commitment source</span></article>
        <article><small>Actual expenses</small><strong>Not integrated</strong><span>No expense ledger source</span></article>
        <article><small>Available approved authority</small><strong>{{ dashboard?.available_to_allocate?.length ? dashboard.available_to_allocate.map(x => money(x.amount, x.currency)).join(' ? ') : 'Not recorded' }}</strong><span>Approved line authority less existing allocations</span></article>
        <article><small>Forecast funding shortfall</small><strong>{{ Array.isArray(dashboard?.forecast_shortfall) ? dashboard.forecast_shortfall.map(x => money(x.shortfall, x.currency)).join(' ? ') : dashboard?.forecast_shortfall || 'Not recorded' }}</strong><span>Against approved requirement allocations; excludes provisional unpriced demand</span></article>
      </section>
      <section class="budget-panel"><div class="budget-panel-head"><div><h2>Shipment funding demand</h2><p>Approved and provisional estimate costs stay in separate totals. Provisional amounts do not authorize budget allocations.</p></div><a href="/accounting/funding-requirements">View requirements →</a></div><div class="budget-chart-list"><article v-for="row in (dashboard?.demand?.by_category || [])" :key="row.currency + row.category"><span>{{ row.category.replaceAll('_', ' ') }}</span><b>{{ money(row.amount, row.currency) }}</b><i :style="{ width: `${Math.min(100, row.percent)}%` }"></i></article><p v-if="!dashboard?.demand?.by_category?.length" class="budget-empty">{{ busy ? 'Loading real forecast and estimate data…' : 'No approved estimate funding requirements are recorded for this period.' }}</p></div><div v-if="dashboard?.demand?.provisional_by_category?.length" class="budget-provisional"><h3>Provisional assumptions · excluded from approved totals</h3><p v-for="row in dashboard.demand.provisional_by_category" :key="row.currency + row.category">{{ row.category.replaceAll('_', ' ') }} · {{ money(row.amount, row.currency) }}</p></div></section>
      <div class="budget-two-col"><section class="budget-panel"><div class="budget-panel-head"><div><h2>Upcoming funding needs</h2><p>Expected due dates are not present in the source estimate data.</p></div></div><p class="budget-empty">Payment timing is not recorded. Forecast month is shown as demand timing only.</p></section><section class="budget-panel"><div class="budget-panel-head"><div><h2>Commitments and actuals</h2><p>Expense and cash sources have not been integrated.</p></div></div><p class="budget-empty">Committed amount: Not integrated · Actual incurred expenses: Not integrated · Verified cash: Not recorded.</p></section></div>
    </template>

    <template v-else-if="view === 'funding-requirements' || view === 'shipment-demand' || view === 'cash-forecast'">
      <section class="budget-panel"><div v-if="view === 'cash-forecast'" class="budget-period-tabs" role="group" aria-label="Cash forecast period"><button v-for="[key, label] in [['day', 'Daily'], ['week', 'Weekly'], ['month', 'Monthly']]" :key="key" :class="{ active: cashPeriod === key }" @click="cashPeriod = key">{{ label }}</button></div><div class="budget-filters"><input v-model="filters.month" type="month" aria-label="Forecast month"><input v-model="filters.client" placeholder="Filter client" aria-label="Filter client"><select v-model="filters.mode"><option value="">All shipment modes</option><option>Sea</option><option>Air</option><option>Road</option><option>Rail</option></select><select v-if="view !== 'shipment-demand'" v-model="filters.status"><option value="">All source statuses</option><option value="provisional">Unpriced forecast</option><option value="provisional_estimate">Provisional estimate</option><option value="approved_estimate">Approved estimate</option></select><button class="budget-refresh" @click="load">Apply filters</button></div><div v-if="view !== 'cash-forecast' || cashPeriod === 'month'" class="budget-table-wrap"><table><thead><tr><th>Source / Version</th><th>Client / Inquiry</th><th>Month / Mode</th><th>Category</th><th>Shipments</th><th>Funding amount</th><th>Status</th><th>Due date</th></tr></thead><tbody><tr v-for="row in requirements" :key="row.source_reference"><td><b>{{ row.source_reference }}</b><small>{{ row.source_type.replaceAll('_', ' ') }}</small></td><td>{{ row.client }}<small>{{ row.inquiry_reference }}</small></td><td>{{ row.forecast_month }}<small>{{ row.transport_mode }}</small></td><td>{{ row.category.replaceAll('_', ' ') }}</td><td>{{ row.expected_shipments }}</td><td>{{ money(row.estimated_amount, row.currency) }}</td><td><span class="budget-badge" :class="row.source_status">{{ row.source_status.replaceAll('_', ' ') }}</span></td><td>{{ row.due_date || 'Not recorded' }}</td></tr><tr v-if="!requirements.length"><td colspan="8" class="budget-empty">{{ busy ? 'Loading…' : 'No records match these filters.' }}</td></tr></tbody></table></div><div v-if="view === 'cash-forecast' && cashPeriod !== 'month'" class="budget-empty">{{ cashPeriod === 'day' ? 'Daily payment timing is not recorded.' : 'Weekly payment timing is not recorded.' }} Source records have forecast month only; no expected due dates or payment ledger are integrated.</div><div v-if="view === 'cash-forecast'" class="budget-footnote">No verified cash balance or payment due dates are recorded. Monthly totals represent forecast demand timing only.</div></section>
    </template>

    <template v-else-if="view === 'budget-plans' || view === 'budget-allocations' || view === 'budget-variance' || view === 'budget-history'">
      <div class="budget-manage-layout"><section class="budget-panel"><div class="budget-panel-head"><div><h2>Monthly budget plans</h2><p>Requests and approvals are maintained by currency and version.</p></div></div><div class="budget-table-wrap"><table><thead><tr><th>Reference / Month</th><th>Currency</th><th>Requested</th><th>Approved</th><th v-if="view === 'budget-variance'">Request variance</th><th v-if="view === 'budget-variance'">Approved ? allocated</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="plan in plans" :key="plan.id" :class="{ 'budget-row-active': selected?.data?.id === plan.id }"><td><b>{{ plan.reference }}</b><small>{{ plan.budget_month.slice(0, 7) }} · v{{ plan.version }}</small></td><td>{{ plan.currency }}</td><td>{{ money(plan.requested_total, plan.currency) }}</td><td>{{ money(plan.approved_total, plan.currency) }}</td><td v-if="view === 'budget-variance'">{{ plan.approved_request_variance === null ? 'N/A' : money(plan.approved_request_variance, plan.currency) }}<small>{{ plan.approval_variance_percent === null ? 'N/A baseline' : `${plan.approval_variance_percent}%` }}</small></td><td v-if="view === 'budget-variance'">{{ plan.approved_allocation_variance === null ? 'N/A' : money(plan.approved_allocation_variance, plan.currency) }}</td><td><span class="budget-badge">{{ plan.status.replaceAll('_', ' ') }}</span></td><td><button class="budget-link" @click="openPlan(plan.id)">Open</button></td></tr><tr v-if="!plans.length"><td :colspan="view === 'budget-variance' ? 8 : 6" class="budget-empty">{{ busy ? 'Loading plans…' : 'No monthly budgets have been created.' }}</td></tr></tbody></table></div></section>
      <section v-if="selected" class="budget-panel budget-detail"><div class="budget-panel-head"><div><h2>{{ selected.data.reference }}</h2><p>{{ selected.data.budget_month.slice(0, 7) }} · {{ selected.data.currency }} · {{ selected.data.status.replaceAll('_', ' ') }}</p></div><button v-if="can('budgets.close') && selected.data.status === 'approved'" class="budget-refresh" @click="sendAction(`/api/accounting/budgets/${selected.data.id}/close`, { remarks: 'Accounting closed the approved budget cycle' })">Close budget cycle</button><button v-if="can('budgets.revise') && ['approved','rejected','revision_requested'].includes(selected.data.status)" class="budget-refresh" @click="sendAction(`/api/accounting/budgets/${selected.data.id}/revise`, { reason: 'Budget assumptions or funding requirements changed' })">Create revision</button><button v-if="can('budgets.submit') && selected.data.status === 'draft'" class="ifc-primary" @click="sendAction(`/api/accounting/budgets/${selected.data.id}/submit`, { remarks: 'Submitted for Finance review' })">Submit for approval</button></div><p>{{ selected.data.explanation || 'No assumptions recorded.' }}</p><div v-if="can('budgets.update') && ['draft','revision_requested'].includes(selected.data.status)" class="budget-detail-actions"><button class="budget-refresh" @click="beginEdit">Edit draft</button></div><div class="budget-table-wrap"><table><thead><tr><th>Category</th><th>Requested</th><th>Approved</th><th>Allocated</th></tr></thead><tbody><tr v-for="line in selected.lines" :key="line.id"><td>{{ line.category.replaceAll('_', ' ') }}<small>{{ line.description || '' }}</small></td><td>{{ money(line.requested_amount, selected.data.currency) }}</td><td>{{ money(line.approved_amount, selected.data.currency) }}</td><td>{{ money(selected.allocations.filter(a => a.budget_line_id === line.id).reduce((sum, a) => sum + Number(a.amount), 0), selected.data.currency) }}</td></tr></tbody></table></div><form v-if="can('budgets.review') && ['submitted','under_review'].includes(selected.data.status)" class="budget-review" @submit.prevent="sendAction(`/api/accounting/budgets/${selected.data.id}/review`, { decision: 'approved', remarks: reviewRemarks })"><label>Approval remarks<input v-model="reviewRemarks" required minlength="3" placeholder="Adequacy review and rationale"></label><button type="button" class="budget-refresh" @click="sendAction(`/api/accounting/budgets/${selected.data.id}/review`, { decision: 'under_review', remarks: reviewRemarks || 'Review started' })">Mark under review</button><button class="ifc-primary" :disabled="!can('budgets.approve')">Approve budget</button><button type="button" class="budget-refresh" @click="sendAction(`/api/accounting/budgets/${selected.data.id}/review`, { decision: 'revision_requested', remarks: reviewRemarks || 'Please revise and resubmit' })">Request changes</button><button type="button" class="budget-danger" @click="sendAction(`/api/accounting/budgets/${selected.data.id}/review`, { decision: 'rejected', remarks: reviewRemarks || 'Rejected after review' })">Reject</button></form><form v-if="can('budgets.allocate') && selected.data.status === 'approved'" class="budget-review" @submit.prevent="saveAllocation"><select v-model="allocationForm.budget_line_id"><option v-for="line in selected.lines" :key="line.id" :value="line.id">{{ line.category.replaceAll('_', ' ') }}</option></select><select v-model="allocationForm.requirement_source" required><option value="">Choose approved funding requirement</option><option v-for="item in requirements.filter(r => r.source_status === 'approved_estimate' && r.currency === selected.data.currency && r.category === selected.lines.find(l => l.id === Number(allocationForm.budget_line_id))?.category)" :key="item.source_reference" :value="item.source_reference">{{ item.source_reference }} ? {{ item.client }} ? {{ money(item.estimated_amount, item.currency) }}</option></select><input v-model="allocationForm.amount" type="number" min="0.01" step="0.01" placeholder="Amount" required><input v-model="allocationForm.purpose" placeholder="Allocation purpose" required><button class="ifc-primary">Reserve approved authority</button></form><p v-if="view === 'budget-variance'" class="budget-footnote">Actual, open commitment and FX variance are N/A until their source modules and verified conversion rates are integrated.</p><div v-if="view === 'budget-history'" class="budget-timeline"><article v-for="item in auditHistory" :key="item.id"><b>{{ item.action.replaceAll('_', ' ') }}</b><time>{{ item.created_at }}</time><p>{{ item.reason || 'No reason recorded.' }}</p></article></div></section></div>
      <div v-if="!selected" class="budget-footnote">Select a plan to view its lines and workflow details. {{ view === 'budget-variance' ? 'Request variance is approved minus requested. Approved allocation variance is approved authority minus allocated authority. Commitment versus actual and FX comparisons are unavailable until source integrations and rates exist. Zero request baselines display N/A.' : '' }}</div>
    </template>

    <section v-else-if="view === 'commitments-actuals'" class="budget-panel"><div class="budget-panel-head"><div><h2>Source integrations</h2><p>Financial actuals and operational commitments require authoritative source records.</p></div></div><div class="budget-integration-grid"><article><span>Commitments</span><b>Not integrated</b><small>No purchase order or approved obligation module exists.</small></article><article><span>Actual expenses</span><b>Not integrated</b><small>No incurred expense ledger is connected.</small></article><article><span>Cash disbursements</span><b>Not integrated</b><small>This workspace does not perform payments.</small></article><article><span>Cash advances / liquidation</span><b>Not integrated</b><small>Advance issue and reconciliation records are not available.</small></article></div></section>

    <div v-if="editing" class="budget-overlay" @click.self="editing = false"><form class="budget-modal" @submit.prevent="updatePlan"><header><div><h2>Edit draft budget</h2><p>Only draft plans can be changed. Submitted and approved versions stay locked.</p></div><button type="button" class="budget-close" aria-label="Close" @click="editing = false">?</button></header><label>Explanation and assumptions<textarea v-model="editForm.explanation" rows="3"></textarea></label><div class="budget-lines-head"><h3>Budget lines</h3><button type="button" class="budget-link" @click="editForm.lines.push({ category: 'other', requested_amount: '0.00', description: '' })">+ Add category</button></div><div v-for="(line, index) in editForm.lines" :key="index" class="budget-line-form"><select v-model="line.category"><option v-for="[key, label] in categories" :key="key" :value="key">{{ label }}</option></select><input v-model="line.requested_amount" type="number" min="0" step="0.01" required aria-label="Requested amount"><input v-model="line.description" placeholder="Notes / assumptions"><button type="button" class="budget-danger" @click="editForm.lines.length > 1 && editForm.lines.splice(index, 1)">Remove</button></div><label>Reason for adjustment<input v-model="editForm.reason" placeholder="Optional explanation"></label><footer><button type="button" class="budget-refresh" @click="editing = false">Cancel</button><button class="ifc-primary">Save changes</button></footer></form></div><div v-if="showCreate" class="budget-overlay" @click.self="showCreate = false"><form class="budget-modal" @submit.prevent="createPlan"><header><div><h2>New monthly budget plan</h2><p>Draft requested amounts by category and currency.</p></div><button type="button" class="budget-close" aria-label="Close" @click="showCreate = false">×</button></header><div class="budget-form-grid"><label>Budget month<input v-model="form.budget_month" type="month" required></label><label>Currency<input v-model="form.currency" minlength="3" maxlength="3" required></label></div><label>Explanation and assumptions<textarea v-model="form.explanation" rows="3" placeholder="Planning basis, assumptions, and adjustments"></textarea></label><div class="budget-lines-head"><h3>Budget lines</h3><button type="button" class="budget-link" @click="addLine">+ Add category</button></div><div v-for="(line, index) in form.lines" :key="index" class="budget-line-form"><select v-model="line.category"><option v-for="[key, label] in categories" :key="key" :value="key">{{ label }}</option></select><input v-model="line.requested_amount" type="number" min="0" step="0.01" required aria-label="Requested amount"><input v-model="line.description" placeholder="Notes / assumptions"><button type="button" class="budget-danger" @click="removeLine(index)">Remove</button></div><footer><button type="button" class="budget-refresh" @click="showCreate = false">Cancel</button><button class="ifc-primary">Save draft</button></footer></form></div>
  </div>
</template>
